"""Genera maqueta/data/scian.json: nombres de sector y subsector SCIAN 2018 (a mano) y, para rama (4 dígitos) y subrama (5), ejemplos reales de establecimientos del DENUE de las regiones cargadas.
Uso: python3 -I datos/denue/scian_catalogo.py"""
import json, re, collections
SEC = {'11':'Agricultura, cría y explotación de animales, aprovechamiento forestal, pesca y caza','21':'Minería','22':'Generación y distribución de energía eléctrica, agua y gas','23':'Construcción','31':'Industrias manufactureras (alimentos, bebidas, textiles)','32':'Industrias manufactureras (madera, papel, química, plástico)','33':'Industrias manufactureras (metálicas, maquinaria, muebles)','43':'Comercio al por mayor','46':'Comercio al por menor','48':'Transportes (carga, pasajeros, turismo)','49':'Correos, paquetería y almacenamiento','51':'Información en medios masivos','52':'Servicios financieros y de seguros','53':'Servicios inmobiliarios y alquiler de bienes','54':'Servicios profesionales, científicos y técnicos','55':'Corporativos','56':'Apoyo a los negocios y manejo de residuos','61':'Servicios educativos','62':'Servicios de salud y de asistencia social','71':'Servicios de esparcimiento culturales y deportivos','72':'Alojamiento temporal y preparación de alimentos y bebidas','81':'Otros servicios excepto actividades gubernamentales','93':'Actividades legislativas, gubernamentales y de justicia'}
SUB = {'111':'Agricultura','112':'Cría y explotación de animales','113':'Aprovechamiento forestal','114':'Pesca, caza y captura','115':'Servicios relacionados con actividades agropecuarias y forestales','211':'Extracción de petróleo y gas','212':'Minería de minerales metálicos y no metálicos','213':'Servicios relacionados con la minería','221':'Energía eléctrica, agua y gas por ductos','236':'Edificación','237':'Construcción de obras de ingeniería civil','238':'Trabajos especializados para la construcción','311':'Industria alimentaria','312':'Industria de las bebidas y del tabaco','313':'Insumos textiles y acabado de textiles','314':'Productos textiles, excepto prendas de vestir','315':'Fabricación de prendas de vestir','316':'Cuero, piel y sucedáneos (calzado y artículos)','321':'Industria de la madera','322':'Industria del papel','323':'Impresión e industrias conexas','324':'Productos derivados del petróleo y del carbón','325':'Industria química','326':'Industria del plástico y del hule','327':'Productos a base de minerales no metálicos','331':'Industrias metálicas básicas','332':'Fabricación de productos metálicos','333':'Fabricación de maquinaria y equipo','334':'Equipo de computación, comunicación y electrónico','335':'Aparatos eléctricos y equipo de generación eléctrica','336':'Fabricación de equipo de transporte','337':'Muebles, colchones y persianas','339':'Otras industrias manufactureras','431':'Mayoreo de abarrotes, alimentos, bebidas, hielo y tabaco','432':'Mayoreo de productos textiles y calzado','433':'Mayoreo de farmacia, perfumería, esparcimiento y electrodomésticos','434':'Mayoreo de materias primas agropecuarias, industriales y desechos','435':'Mayoreo de maquinaria, equipo y mobiliario','436':'Mayoreo de camiones y refacciones','437':'Intermediación de comercio al por mayor','461':'Menudeo de abarrotes, alimentos, bebidas, hielo y tabaco','462':'Menudeo en autoservicios y tiendas departamentales','463':'Menudeo de textiles, bisutería, accesorios de vestir y calzado','464':'Menudeo de artículos para el cuidado de la salud','465':'Menudeo de papelería, esparcimiento y artículos de uso personal','466':'Menudeo de enseres domésticos, computadoras y decoración','467':'Menudeo de ferretería, tlapalería y vidrios','468':'Menudeo de vehículos, refacciones, combustibles y lubricantes','469':'Menudeo por Internet, catálogos, TV y similares','481':'Transporte aéreo','482':'Transporte por ferrocarril','483':'Transporte por agua','484':'Autotransporte de carga','485':'Transporte terrestre de pasajeros','486':'Transporte por ductos','487':'Transporte turístico','488':'Servicios relacionados con el transporte','491':'Servicios postales','492':'Mensajería y paquetería','493':'Servicios de almacenamiento','511':'Edición de periódicos, revistas, libros y software','512':'Industria fílmica, del video y del sonido','515':'Radio y televisión','517':'Telecomunicaciones','518':'Procesamiento de información y hospedaje web','519':'Otros servicios de información','521':'Banca central','522':'Intermediación crediticia y financiera no bursátil','523':'Actividades bursátiles, cambiarias e inversión','524':'Seguros, fianzas y pensiones','531':'Servicios inmobiliarios','532':'Alquiler de bienes muebles','533':'Alquiler de marcas, patentes y franquicias','541':'Servicios profesionales, científicos y técnicos','551':'Corporativos','561':'Servicios de apoyo a los negocios','562':'Manejo de residuos y servicios de remediación','611':'Servicios educativos','621':'Servicios médicos de consulta externa','622':'Hospitales','623':'Residencias de asistencia social y cuidado de la salud','624':'Otros servicios de asistencia social','711':'Servicios artísticos, culturales y deportivos','712':'Museos, sitios históricos, zoológicos y similares','713':'Entretenimiento en instalaciones recreativas','721':'Alojamiento temporal','722':'Preparación de alimentos y bebidas','811':'Reparación y mantenimiento','812':'Servicios personales','813':'Asociaciones y organizaciones','814':'Hogares con empleados domésticos','931':'Actividades gubernamentales, legislativas y de justicia'}
norm = lambda s: re.sub(r'\s+', ' ', s.lower()).strip()
cnt = {4: collections.defaultdict(collections.Counter), 5: collections.defaultdict(collections.Counter)}
for reg in ('saltillo', 'monterrey'):
    for p in json.load(open(f'maqueta/data/denue_{reg}.json'))['p']:
        n = norm(p[4]); 
        if len(n) < 4 or 'sin nombre' in n or n.startswith('sin '): continue
        for L in (4, 5): cnt[L][p[5][:L]][n] += 1
ex = {}
for L in (4, 5):
    for c, k in cnt[L].items():
        top = []
        for nm, _ in k.most_common(40):
            t = nm.title()
            if not any(t.lower() in u.lower() or u.lower() in t.lower() for u in top): top.append(t)
            if len(top) == 2: break
        ex[c] = ', '.join(top)
json.dump({'s': SEC, 'ss': SUB, 'ex': ex}, open('maqueta/data/scian.json', 'w', encoding='utf-8'), ensure_ascii=False, separators=(',', ':'))
print(len(ex), list(ex.items())[:6])
